#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
named FW_GROUP_PORT fws_tcp-443_80 && fail 'a port group named fws_tcp-443_80 exists; nothing was written'
named FW_GROUP_IP fws_asg-web && fail 'an IP group named fws_asg-web exists; nothing was written'
named FW_GROUP_IP fws_nsg-web_Allow-SSH-Admins_src && fail 'an IP group named fws_nsg-web_Allow-SSH-Admins_src exists; nothing was written'
named FW_GROUP_IP fws_AzureLoadBalancer && fail 'an IP group named fws_AzureLoadBalancer exists; nothing was written'
named FW_GROUP_IP fws_Storage.WestEurope && fail 'an IP group named fws_Storage.WestEurope exists; nothing was written'
named FW_GROUP_IP fws_asg-db && fail 'an IP group named fws_asg-db exists; nothing was written'
named FW_GROUP_IP fws_Sql.WestEurope && fail 'an IP group named fws_Sql.WestEurope exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_asg-web --set .COMMENT 'FWShift: asg-web'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.30.1.10/31
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_nsg-web_Allow-SSH-Admins_src --set .COMMENT 'FWShift: 198.51.100.0/24, 192.0.2.128/25'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.0.2.128/25
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 198.51.100.0/24
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_AzureLoadBalancer --set .COMMENT 'FWShift: AzureLoadBalancer'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 168.63.129.16
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Storage.WestEurope --set .COMMENT 'FWShift: Storage.WestEurope'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.64/26
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_asg-db --set .COMMENT 'FWShift: asg-db'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.30.3.20
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Sql.WestEurope --set .COMMENT 'FWShift: Sql.WestEurope'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.128/27
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_tcp-443_80 --set .COMMENT 'FWShift: tcp-443,80'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
